import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matvec_f32(
    .param .u64 .ptr .align 8 param_A,
    .param .u64 .ptr .align 8 param_B,
    .param .u64 .ptr .align 8 param_C,
    .param .u32 param_M,
    .param .u32 param_K,
    .param .u32 param_SLICE,
    .param .u32 param_NSPLIT
)
.reqntid 128
{
    .reg .pred %p<8>;
    .reg .b32  %r<32>;
    .reg .b64  %rd<32>;
    .reg .f32  %f<32>;
    // Four reduced row sums for the CTA row tile: ROWS * 128 floats.
    .shared .align 4 .b8 smem[2048];
    ld.param.u64 %rd1, [param_A];
    ld.param.u64 %rd2, [param_B];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r1,  [param_M];
    ld.param.u32 %r2,  [param_K];
    ld.param.u32 %r10, [param_SLICE];
    ld.param.u32 %r11, [param_NSPLIT];
    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ctaid.y;
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r5, %ntid.x;
    // ROWS=4 row tile owned by this CTA; ctaid.y is a row-tile index.
    shl.b32 %r17, %r4, 2;
    setp.ge.u32 %p1, %r17, %r1;
    @%p1 bra DONE;
    // Split-K slice bounds: start = slice_id * SLICE elements; every
    // slice except the last covers SLICE elements (multiple of 4), the
    // last slice takes the remainder, so all v4 accesses stay in bounds.
    mul.lo.u32 %r13, %r12, %r10;
    sub.u32 %r14, %r11, 1;
    setp.eq.u32 %p2, %r12, %r14;
    sub.u32 %r16, %r2, %r13;
    selp.u32 %r15, %r16, %r10, %p2;
    shr.u32 %r6, %r15, 2;
    cvt.u64.u32 %rd5, %r13;
    // Row stride in bytes and four consecutive row base pointers.
    mul.wide.u32 %rd14, %r2, 4;
    mul.wide.u32 %rd4, %r17, %r2;
    add.u64 %rd4, %rd4, %rd5;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rd1;
    add.u64 %rd15, %rd4, %rd14;
    add.u64 %rd16, %rd15, %rd14;
    add.u64 %rd17, %rd16, %rd14;
    // B slice base pointer: B + start * 4 bytes.
    shl.b64 %rd11, %rd5, 2;
    add.u64 %rd11, %rd11, %rd2;
    // Generic address of shared reduction buffer.
    mov.u64 %rd18, smem;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;
    mov.u32 %r7, %r3;
LOOP:
    setp.ge.u32 %p1, %r7, %r6;
    @%p1 bra RED;
    mul.wide.u32 %rd12, %r7, 16;
    // Load the shared B vector once per CTA row-tile iteration.
    add.u64 %rd13, %rd11, %rd12;
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd13];
    // Four independent A row streams reuse the same B registers.
    add.u64 %rd6, %rd4, %rd12;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd6];
    add.u64 %rd7, %rd15, %rd12;
    ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%rd7];
    add.u64 %rd8, %rd16, %rd12;
    ld.global.v4.f32 {%f17, %f18, %f19, %f20}, [%rd8];
    add.u64 %rd9, %rd17, %rd12;
    ld.global.v4.f32 {%f21, %f22, %f23, %f24}, [%rd9];
    fma.rn.f32 %f1, %f5,  %f9,  %f1;
    fma.rn.f32 %f1, %f6,  %f10, %f1;
    fma.rn.f32 %f1, %f7,  %f11, %f1;
    fma.rn.f32 %f1, %f8,  %f12, %f1;
    fma.rn.f32 %f2, %f13, %f9,  %f2;
    fma.rn.f32 %f2, %f14, %f10, %f2;
    fma.rn.f32 %f2, %f15, %f11, %f2;
    fma.rn.f32 %f2, %f16, %f12, %f2;
    fma.rn.f32 %f3, %f17, %f9,  %f3;
    fma.rn.f32 %f3, %f18, %f10, %f3;
    fma.rn.f32 %f3, %f19, %f11, %f3;
    fma.rn.f32 %f3, %f20, %f12, %f3;
    fma.rn.f32 %f4, %f21, %f9,  %f4;
    fma.rn.f32 %f4, %f22, %f10, %f4;
    fma.rn.f32 %f4, %f23, %f11, %f4;
    fma.rn.f32 %f4, %f24, %f12, %f4;
    add.u32 %r7, %r7, %r5;
    bra LOOP;
