    // Store four per-thread partial row sums, row-major by 128 threads.
    mul.wide.u32 %rd19, %r3, 4;
    add.u64 %rd19, %rd19, %rd18;
    st.shared.f32 [%rd19], %f1;
    add.u64 %rd20, %rd19, 512;
    st.shared.f32 [%rd20], %f2;
    add.u64 %rd21, %rd19, 1024;
    st.shared.f32 [%rd21], %f3;
    add.u64 %rd22, %rd19, 1536;
    st.shared.f32 [%rd22], %f4;
    bar.sync 0;
    // Tree reduction over 128 threads for all four rows simultaneously.
    mov.u32 %r8, 64;
RLOOP:
    setp.ge.u32 %p1, %r3, %r8;
    @%p1 bra RSKIP;
    shl.b32 %r22, %r8, 2;
    cvt.u64.u32 %rd23, %r22;
    mov.u64 %rd20, %rd19;
    add.u64 %rd24, %rd20, %rd23;
    ld.shared.f32 %f25, [%rd24];
    ld.shared.f32 %f26, [%rd20];
    add.f32 %f26, %f26, %f25;
    st.shared.f32 [%rd20], %f26;
    add.u64 %rd20, %rd19, 512;
    add.u64 %rd24, %rd20, %rd23;
    ld.shared.f32 %f25, [%rd24];
    ld.shared.f32 %f26, [%rd20];
    add.f32 %f26, %f26, %f25;
    st.shared.f32 [%rd20], %f26;
    add.u64 %rd20, %rd19, 1024;
    add.u64 %rd24, %rd20, %rd23;
    ld.shared.f32 %f25, [%rd24];
    ld.shared.f32 %f26, [%rd20];
    add.f32 %f26, %f26, %f25;
    st.shared.f32 [%rd20], %f26;
    add.u64 %rd20, %rd19, 1536;
    add.u64 %rd24, %rd20, %rd23;
    ld.shared.f32 %f25, [%rd24];
    ld.shared.f32 %f26, [%rd20];
    add.f32 %f26, %f26, %f25;
    st.shared.f32 [%rd20], %f26;
RSKIP:
    bar.sync 0;
    shr.u32 %r8, %r8, 1;
    setp.ne.u32 %p1, %r8, 0;
    @%p1 bra RLOOP;
    // Thread 0 atomically accumulates this slice's four row sums.
    setp.ne.u32 %p1, %r3, 0;
    @%p1 bra DONE;
    mov.u32 %r18, %r17;
    mov.u64 %rd24, %rd18;
    mul.wide.u32 %rd20, %r18, 4;
    add.u64 %rd20, %rd20, %rd3;
    ld.shared.f32 %f25, [%rd24];
    setp.lt.u32 %p3, %r18, %r1;
    @%p3 red.global.add.f32 [%rd20], %f25;
    add.u32 %r18, %r18, 1;
    add.u64 %rd24, %rd24, 512;
    mul.wide.u32 %rd20, %r18, 4;
    add.u64 %rd20, %rd20, %rd3;
    ld.shared.f32 %f25, [%rd24];
    setp.lt.u32 %p3, %r18, %r1;
    @%p3 red.global.add.f32 [%rd20], %f25;
    add.u32 %r18, %r18, 1;
    add.u64 %rd24, %rd24, 512;
    mul.wide.u32 %rd20, %r18, 4;
    add.u64 %rd20, %rd20, %rd3;
    ld.shared.f32 %f25, [%rd24];
    setp.lt.u32 %p3, %r18, %r1;
    @%p3 red.global.add.f32 [%rd20], %f25;
    add.u32 %r18, %r18, 1;
    add.u64 %rd24, %rd24, 512;
    mul.wide.u32 %rd20, %r18, 4;
    add.u64 %rd20, %rd20, %rd3;
    ld.shared.f32 %f25, [%rd24];
    setp.lt.u32 %p3, %r18, %r1;
    @%p3 red.global.add.f32 [%rd20], %f25;
DONE:
    ret;
